 $('#activePartner').innerHTML=`<div class="partner-main"><div class="partner-sprite">${sprite(p.key)}</div><div class="partner-info"><span class="eyebrow">${p.key===state.starter?'SEU POKÉMON':'PARCEIRO'}</span><strong>${DEX[p.key].name}</strong><small>${DEX[p.key].type}</small></div></div><div class="partner-hp"><div><span>Energia</span><b>${state.hp} / ${state.maxHp}</b></div><div class="hp-track"><i style="width:${hpBar(state.hp,state.maxHp)}%"></i></div></div>`;
